import { Factory, Package, TrendingUp } from 'lucide-react';

import { formatCompact, formatDate, formatNumber, formatPercent } from '@/governance/lib/format';
import { useSql } from '@/governance/lib/use-sql';
import {
  BarChart,
  Badge,
  ChartCard,
  DataTable,
  KpiCard,
  LineChart,
  ReportGrid,
  ReportShell,
} from '@/governance/ui';

/*
 * Sample data, generated by Snowflake itself — no table needed, so this page
 * works as soon as your login works. Replace both queries with real ones.
 */
const TREND_SQL = `
select
  dateadd(day, seq4() - 29, current_date()) as DAY,
  uniform(900, 1500, random()) as CASES,
  round(uniform(700, 980, random()) / 10, 1) as YIELD_PCT
from table(generator(rowcount => 30))
order by DAY
`;

const BY_PLANT_SQL = `
select
  'Plant ' || chr(65 + seq4()) as PLANT,
  uniform(4000, 26000, random()) as CASES
from table(generator(rowcount => 6))
order by CASES desc
`;

export function Dashboard() {
  const trend = useSql(TREND_SQL);
  const byPlant = useSql(BY_PLANT_SQL);

  const totalCases = trend.rows.reduce((sum, row) => sum + Number(row.CASES), 0);
  const latest = trend.rows.at(-1);
  const previous = trend.rows.at(-2);
  const dayOverDay =
    latest && previous ? (Number(latest.CASES) - Number(previous.CASES)) / Number(previous.CASES) : 0;
  const avgYield =
    trend.rows.length > 0
      ? trend.rows.reduce((sum, row) => sum + Number(row.YIELD_PCT), 0) / trend.rows.length
      : 0;

  return (
    <ReportShell
      title="Production overview"
      description="Last 30 days"
      toolbar={<Badge variant="warning">Sample data</Badge>}
    >
      <ReportGrid columns={3} className="mb-4">
        <KpiCard.Root status={trend.status} error={trend.error}>
          <KpiCard.Header icon={<Package />}>
            <KpiCard.Label>Total cases</KpiCard.Label>
          </KpiCard.Header>
          <KpiCard.Value>{formatCompact(totalCases)}</KpiCard.Value>
          <KpiCard.Delta sentiment={dayOverDay >= 0 ? 'good' : 'bad'}>
            {formatPercent(dayOverDay, { sign: true })} vs yesterday
          </KpiCard.Delta>
        </KpiCard.Root>

        <KpiCard.Root status={trend.status} error={trend.error}>
          <KpiCard.Header icon={<TrendingUp />}>
            <KpiCard.Label>Average yield</KpiCard.Label>
          </KpiCard.Header>
          <KpiCard.Value>{formatPercent(avgYield, { alreadyPercent: true })}</KpiCard.Value>
          <KpiCard.Delta>across all plants</KpiCard.Delta>
        </KpiCard.Root>

        <KpiCard.Root status={byPlant.status} error={byPlant.error}>
          <KpiCard.Header icon={<Factory />}>
            <KpiCard.Label>Plants reporting</KpiCard.Label>
          </KpiCard.Header>
          <KpiCard.Value>{byPlant.rows.length}</KpiCard.Value>
          <KpiCard.Delta>all online</KpiCard.Delta>
        </KpiCard.Root>
      </ReportGrid>

      <ReportGrid columns={2} className="mb-4">
        <ChartCard.Root status={trend.status} error={trend.error}>
          <ChartCard.Header>
            <ChartCard.Title>Daily volume</ChartCard.Title>
            <ChartCard.Subtitle>Cases produced per day</ChartCard.Subtitle>
          </ChartCard.Header>
          <ChartCard.Content>
            <LineChart
              area
              labels={trend.rows.map((row) => formatDate(row.DAY))}
              series={[{ label: 'Cases', data: trend.rows.map((row) => Number(row.CASES)) }]}
            />
          </ChartCard.Content>
          <ChartCard.Footer>Source: Snowflake</ChartCard.Footer>
        </ChartCard.Root>

        <ChartCard.Root status={byPlant.status} error={byPlant.error}>
          <ChartCard.Header>
            <ChartCard.Title>Volume by plant</ChartCard.Title>
            <ChartCard.Subtitle>Cases, last 30 days</ChartCard.Subtitle>
          </ChartCard.Header>
          <ChartCard.Content>
            <BarChart
              horizontal
              labels={byPlant.rows.map((row) => row.PLANT)}
              series={[{ label: 'Cases', data: byPlant.rows.map((row) => Number(row.CASES)) }]}
            />
          </ChartCard.Content>
          <ChartCard.Footer>Source: Snowflake</ChartCard.Footer>
        </ChartCard.Root>
      </ReportGrid>

      <ChartCard.Root status={trend.status} error={trend.error}>
        <ChartCard.Header>
          <ChartCard.Title>Daily detail</ChartCard.Title>
        </ChartCard.Header>
        <ChartCard.Content className="min-h-0 px-0">
          <DataTable
            result={trend}
            columns={[
              { key: 'DAY', label: 'Day', format: (value) => formatDate(value) },
              { key: 'CASES', label: 'Cases', align: 'right', format: (value) => formatNumber(value) },
              {
                key: 'YIELD_PCT',
                label: 'Yield',
                align: 'right',
                format: (value) => formatPercent(value, { alreadyPercent: true }),
              },
            ]}
          />
        </ChartCard.Content>
      </ChartCard.Root>
    </ReportShell>
  );
}
